def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    shirt_patches = image_patch.find("shirt")
    motorcycle_patches = image_patch.find("motorcycle")

    if not man_patches or not shirt_patches or not motorcycle_patches:
        return image_patch

    man_shirt_pairs = []
    for man in man_patches:
        for shirt in shirt_patches:
            if man.overlaps_with(shirt.left, shirt.lower, shirt.right, shirt.upper):
                man_shirt_pairs.append((man, shirt))

    if not man_shirt_pairs:
        return image_patch

    man_shirt_distances = []
    for man, shirt in man_shirt_pairs:
        man_motorcycle_pairs = [(man, motorcycle) for motorcycle in motorcycle_patches if man.overlaps_with(motorcycle.left, motorcycle.lower, motorcycle.right, motorcycle.upper)]
        if man_motorcycle_pairs:
            min_distance = min(distance(man, motorcycle) for _, motorcycle in man_motorcycle_pairs)
            man_shirt_distances.append((man, shirt, min_distance))

    if not man_shirt_distances:
        return image_patch

    man_shirt_distances.sort(key=lambda x: x[2])
    return man_shirt_distances[0][0]

